import{_ as i,c as a,o as e,a2 as t}from"./chunks/framework.PGES7OoM.js";const c=JSON.parse('{"title":"registerWithPrivateKeys","description":"Register a new Curvy handle from raw spending and viewing private keys.","frontmatter":{"editLink":false,"rawMarkdown":"# registerWithPrivateKeys\\n\\nRegister a new Curvy handle from raw spending and viewing private keys.\\n\\n## Import\\n\\n```ts\\nimport { registerWithPrivateKeys } from \\"@0xcurvy/curvy-sdk/actions\\";\\n```\\n\\n## Usage\\n\\n```ts\\nconst account = await registerWithPrivateKeys({ s, v, handle, userAddress });\\n```\\n\\n## Signature\\n\\n```ts\\nfunction registerWithPrivateKeys(parameters: RegisterWithPrivateKeysParameters): Promise<CurvyAccount>\\n```\\n\\n## Returns\\n\\n`Promise<CurvyAccount>`\\n\\nThe action resolves or returns the value shown in the signature.\\n\\n## Parameters\\n\\n### `s`\\n\\n- **Type:** `string`\\n- **Required:** yes\\n\\nThe lowercase Curvy spending private key.\\n\\n```ts\\nconst result = await registerWithPrivateKeys({\\n  s, // [!code focus]\\n  v,\\n  handle,\\n  userAddress,\\n});\\n```\\n\\n### `v`\\n\\n- **Type:** `string`\\n- **Required:** yes\\n\\nThe lowercase Curvy viewing private key.\\n\\n```ts\\nconst result = await registerWithPrivateKeys({\\n  s,\\n  v, // [!code focus]\\n  handle,\\n  userAddress,\\n});\\n```\\n\\n### `handle`\\n\\n- **Type:** `CurvyId`\\n- **Required:** yes\\n\\nThe Curvy handle to register.\\n\\n```ts\\nconst result = await registerWithPrivateKeys({\\n  s,\\n  v,\\n  handle, // [!code focus]\\n  userAddress,\\n});\\n```\\n\\n### `userAddress`\\n\\n- **Type:** `HexString`\\n- **Required:** yes\\n\\nThe wallet address that will own the registered handle.\\n\\n```ts\\nconst result = await registerWithPrivateKeys({\\n  s,\\n  v,\\n  handle,\\n  userAddress, // [!code focus]\\n});\\n```\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig`\\n- **Required:** no\\n\\nCurvy config to use. Defaults to the ambient config.\\n\\n```ts\\nconst result = await registerWithPrivateKeys({\\n  s,\\n  v,\\n  handle,\\n  userAddress,\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nErrors from config resolution and the underlying SDK operation are propagated to the caller.\\n\\n## Related\\n\\n- [Authentication guide](/for-programmers/authentication)\\n- [`register`](/sdk/actions/auth/register) — Register a new Curvy handle from an account signature.\\n- [`registerWithPasskey`](/sdk/actions/auth/registerWithPasskey) — Register a new Curvy handle via a passkey PRF output.\\n\\n## Source\\n\\n[packages/@0xcurvy/sdk/src/actions/auth/registerWithPrivateKeys.ts](https://github.com/0xCurvy/curvy-monorepo/blob/main/packages/@0xcurvy/sdk/src/actions/auth/registerWithPrivateKeys.ts)\\n","rawMarkdownPath":"/_raw/sdk/actions/auth/registerWithPrivateKeys.md","rawMarkdownTitle":"registerWithPrivateKeys","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/auth/registerWithPrivateKeys.md"},"headers":[],"params":{"sdkReferenceKind":"action","category":"auth","action":"registerWithPrivateKeys"},"relativePath":"sdk/actions/auth/registerWithPrivateKeys.md","filePath":"sdk/actions/[category]/[action].md","lastUpdated":1786448401000}'),n={name:"sdk/actions/auth/registerWithPrivateKeys.md"};function r(h,s,l,p,d,o){return e(),a("div",null,[...s[0]||(s[0]=[t("",38)])])}const g=i(n,[["render",r]]);export{c as __pageData,g as default};
